def main():
    catalog_path = ROOT / 'content/articles/catalog.json'
    catalog = json.loads(catalog_path.read_text())
    projects = json.loads((ROOT / 'curriculum/catalog.json').read_text())
    for offset, article in enumerate(ARTICLES):
        project = projects[36 + offset]
        text = '\n\n'.join('## ' + title + '\n' + paragraph for title, paragraph in article['sections'])
        source = (ROOT / 'curriculum/solutions' / (project['key'] + '.py')).read_text().split("if __name__ == '__main__':", 1)[0].strip()
        text += '\n\n## نمونه‌کد و قرارداد پروژه\n' + project['input'] + '\n\n' + project['output']
        text += '\n\n```python\n' + source + '\n\nprint(solve(' + repr(project['example']['input']) + '))\n```'
        text += '\n\n### خروجی مورد انتظار\n```json\n' + json.dumps(project['example']['output'], ensure_ascii=False, indent=2) + '\n```'
        text += '\n\n## پرسش‌های متداول\n' + '\n\n'.join('### ' + q + '\n' + answer for q, answer in article['faq'])
        text += '\n\n## تمرین عملی و قدم بعدی\nپروژهٔ «' + project['title'] + '» همین قرارداد را در میزکار ارزیابی می‌کند. ابتدا خروجی نمونه را دستی محاسبه کنید، سپس تابع را اجرا کنید و یک ورودی مرزی متفاوت بسازید. نمونه‌کد راهی برای توضیح منطق است؛ برای یادگیری، علت هر شرط و انتخاب ساختار داده را بدون نگاه‌کردن به کد توضیح دهید. اجرای موفق با قبولی ارزیابی متفاوت است؛ نتیجه باید برای تمام حالت‌های تعریف‌شده درست بماند.\n'
        (ROOT / 'content/articles' / (article['slug'] + '.txt')).write_text(text)
        entry = {key: article[key] for key in ('slug', 'title', 'seo_title', 'description', 'category')}
        entry.update(series='python-practice', published_at='2026-10-23', project_index=36 + offset,
                     sources=[{'title': article['source'][0], 'url': article['source'][1]}],
                     related=[ARTICLES[(offset + 1) % len(ARTICLES)]['slug'], 'python-for-data', 'python-basics-testing'])
        existing = next((i for i, a in enumerate(catalog) if a['slug'] == article['slug']), None)
        if existing is None:
            catalog.append(entry)
        else:
            catalog[existing] = entry
    catalog_path.write_text(json.dumps(catalog, ensure_ascii=False, indent=2) + '\n')


if __name__ == '__main__':
    main()
